/* HEXA BATTLEGROUNDS setup — PART 11 OF 19. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-binary-6', 'binary', 'mission', 'Badge Reader', 'tech', 1, array['hexavarsity','learning','phase2','stg','helpdesk']::text[], 'A stolen access badge flashed its lights. Rebuild the word it encodes.', '{"scout":{"title":"Badge light capture","body":"Tag J:  ○ ○ ● ○ ●\nTag T:  ● ● ○ ○ ●\nTag X:  ○ ○ ○ ● ○\nTag W:  ● ○ ● ○ ○","mono":true},"decoder":{"title":"Reader protocol","body":"● = 1 and ○ = 0. Each row is a 5-bit binary number.\nBit values from left to right: 16 8 4 2 1.\nThe number is the letter''s position in the alphabet (1 = A, 2 = B … 26 = Z)."},"intel":{"title":"Read order","body":"Read the tags in this order:\nX → T → W → J"}}'::jsonb, '[{"label":"Badge word","accept":["BYTE"]}]'::jsonb, false, 3, 200, 'It is a 4-letter tech word.', 'X=2=B, T=25=Y, W=20=T, J=5=E → BYTE.', null, 25, 'published'), ('mission-binary-7', 'binary', 'mission', 'Badge Reader', 'tech', 1, array['hexavarsity','learning','phase2','stg','helpdesk']::text[], 'A stolen access badge flashed its lights. Rebuild the word it encodes.', '{"scout":{"title":"Badge light capture","body":"Tag H:  ○ ● ○ ● ●\nTag V:  ● ○ ○ ● ●\nTag M:  ● ○ ● ○ ○\nTag R:  ○ ○ ○ ● ●\nTag P:  ○ ○ ○ ○ ●","mono":true},"decoder":{"title":"Reader protocol","body":"● = 1 and ○ = 0. Each row is a 5-bit binary number.\nBit values from left to right: 16 8 4 2 1.\nThe number is the letter''s position in the alphabet (1 = A, 2 = B … 26 = Z)."},"intel":{"title":"Read order","body":"Read the tags in this order:\nV → M → P → R → H"}}'::jsonb, '[{"label":"Badge word","accept":["STACK"]}]'::jsonb, false, 3, 200, 'It is a 5-letter tech word.', 'V=19=S, M=20=T, P=1=A, R=3=C, H=11=K → STACK.', null, 25, 'published'), ('mission-grid-0', 'grid', 'mission', 'Coordinate Drop', 'observation', 2, array['terrace','glass','observation','public']::text[], 'A supply crate is marked on a letter grid. Read the drop code from the marked squares.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5\n1 | G Y C T N\n2 | T N Y E R\n3 | I R Y R Z\n4 | S H B V X\n5 | V N A T K","mono":true},"decoder":{"title":"Marked coordinates","body":"(3, 1)  (4, 3)  (3, 5)  (1, 2)  (4, 2)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["CRATE"]}]'::jsonb, false, 3, 200, 'The code is a 5-letter word ending in E.', 'Reading (column,row) gives CRATE; reading it as (row,column) gives nonsense (IBZYH).', null, 25, 'published'), ('mission-grid-1', 'grid', 'mission', 'Coordinate Drop', 'observation', 2, array['terrace','glass','observation','public']::text[], 'A supply crate is marked on a letter grid. Read the drop code from the marked squares.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5\n1 | D F N R A\n2 | I J U M B\n3 | A W C W L\n4 | U N T G K\n5 | C G K S Z","mono":true},"decoder":{"title":"Marked coordinates","body":"(4, 5)  (1, 2)  (2, 5)  (3, 1)  (5, 1)  (5, 3)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["SIGNAL"]}]'::jsonb, false, 3, 200, 'The code is a 6-letter word ending in L.', 'Reading (column,row) gives SIGNAL; reading it as (row,column) gives nonsense (KFBACK).', null, 25, 'published'), ('mission-grid-2', 'grid', 'mission', 'Coordinate Drop', 'observation', 2, array['terrace','glass','observation','public']::text[], 'A supply crate is marked on a letter grid. Read the drop code from the marked squares.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5\n1 | L P S T U\n2 | Q B S P A\n3 | P Y O K L\n4 | V H S S N\n5 | F Y M K N","mono":true},"decoder":{"title":"Marked coordinates","body":"(3, 4)  (5, 1)  (1, 3)  (2, 1)  (5, 3)  (2, 3)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["SUPPLY"]}]'::jsonb, false, 3, 200, 'The code is a 6-letter word ending in Y.', 'Reading (column,row) gives SUPPLY; reading it as (row,column) gives nonsense (KFSQMS).', null, 25, 'published'), ('mission-grid-3', 'grid', 'mission', 'Coordinate Drop', 'observation', 2, array['terrace','glass','observation','public']::text[], 'A supply crate is marked on a letter grid. Read the drop code from the marked squares.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5\n1 | F I R L S\n2 | U K K T O\n3 | L A P J C\n4 | T T G I N\n5 | M A K X Y","mono":true},"decoder":{"title":"Marked coordinates","body":"(5, 1)  (2, 1)  (3, 4)  (5, 4)  (2, 5)  (1, 3)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["SIGNAL"]}]'::jsonb, false, 3, 200, 'The code is a 6-letter word ending in L.', 'Reading (column,row) gives SIGNAL; reading it as (row,column) gives nonsense (MUJXOR).', null, 25, 'published'), ('mission-grid-4', 'grid', 'mission', 'Coordinate Drop', 'observation', 2, array['terrace','glass','observation','public']::text[], 'A supply crate is marked on a letter grid. Read the drop code from the marked squares.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5\n1 | J W E E T\n2 | K C R R T\n3 | D F O T R\n4 | J B O E F\n5 | O A W X Y","mono":true},"decoder":{"title":"Marked coordinates","body":"(5, 2)  (1, 5)  (2, 1)  (4, 1)  (4, 2)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["TOWER"]}]'::jsonb, false, 3, 200, 'The code is a 5-letter word ending in R.', 'Reading (column,row) gives TOWER; reading it as (row,column) gives nonsense (ATKJB).', null, 25, 'published'), ('mission-grid-5', 'grid', 'mission', 'Coordinate Drop', 'observation', 2, array['terrace','glass','observation','public']::text[], 'A supply crate is marked on a letter grid. Read the drop code from the marked squares.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5\n1 | O U U E S\n2 | V O I Y P\n3 | M S M E N\n4 | T P R T Y\n5 | L O U J F","mono":true},"decoder":{"title":"Marked coordinates","body":"(2, 3)  (2, 1)  (2, 4)  (5, 2)  (1, 5)  (5, 4)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["SUPPLY"]}]'::jsonb, false, 3, 200, 'The code is a 6-letter word ending in Y.', 'Reading (column,row) gives SUPPLY; reading it as (row,column) gives nonsense (IVYOSJ).', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end,